/* From Uiverse.io by Satwinder04 - Tags: loader */
.__UIV_SCOPE__ .loader3 {
  display: flex;
  justify-content: center;
  align-items: center;
}

.__UIV_SCOPE__ .circle1 {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  margin: 0 10px;
  background-color: #333;
  animation: circle1 1s ease-in-out infinite;
}

.__UIV_SCOPE__ .circle1:nth-child(2) {
  animation-delay: 0.2s;
}

.__UIV_SCOPE__ .circle1:nth-child(3) {
  animation-delay: 0.4s;
}

.__UIV_SCOPE__ .circle1:nth-child(4) {
  animation-delay: 0.6s;
}

.__UIV_SCOPE__ .circle1:nth-child(5) {
  animation-delay: 0.8s;
}

@keyframes circle1 {
  0% {
    transform: scale(1);
    opacity: 1;
  }

  50% {
    transform: scale(1.5);
    opacity: 0.5;
  }

  100% {
    transform: scale(1);
    opacity: 1;
  }
}
